// modules/ui/cards/AbstractUiCard.ts
class AbstractUiCard {
  context;
  _isVisible;
  $parent;
  $wrap;
  constructor(context2) {
    this.context = context2;
    this._isVisible = false;
    this.$parent = null;
    this.$wrap = null;
    this.show = this.show.bind(this);
    this.hide = this.hide.bind(this);
    this.toggle = this.toggle.bind(this);
  }
  get visible() {
    return this._isVisible;
  }
  show(e3) {
    e3?.preventDefault();
    if (this._isVisible) {
      this.render();
      return;
    }
    this._isVisible = true;
    this.render();
    if (!this.$wrap)
      return;
    this.$wrap.interrupt().style("display", null).style("opacity", "0").transition().duration(200).style("opacity", "1");
  }
  hide(e3) {
    e3?.preventDefault();
    if (!this.$wrap)
      return;
    if (!this._isVisible)
      return;
    this._isVisible = false;
    this.$wrap.interrupt().transition().duration(200).style("opacity", "0").on("end", () => this.$wrap?.style("display", "none"));
  }
  toggle(e3) {
    if (this._isVisible) {
      this.hide(e3);
    } else {
      this.show(e3);
    }
  }
}
