var DIRECTIONS = [
  ["top", [0, -0.5]],
  ["left", [-0.5, 0]],
  ["right", [0.5, 0]],
  ["bottom", [0, 0.5]]
];

class UiSectionBackgroundOffset extends AbstractUiSection {
  constructor(context2) {
    super(context2, "background-offset");
    const imagery = context2.systems.imagery;
    this._updateValue = this._updateValue.bind(this);
    this._inputOffset = this._inputOffset.bind(this);
    this._pointerdown = this._pointerdown.bind(this);
    imagery.on("imagerychange", this._updateValue);
  }
  label() {
    const l10n = this.context.systems.l10n;
    return l10n.t("background.fix_misalignment");
  }
  _updateValue() {
    const context2 = this.context;
    const imagery = context2.systems.imagery;
    const meters = geoOffsetToMeters(imagery.offset);
    const x3 = +meters[0].toFixed(2);
    const y3 = +meters[1].toFixed(2);
    context2.container().selectAll(".nudge-inner-rect").select("input").classed("error", false).property("value", `${x3},${y3}`);
    context2.container().selectAll(".nudge-reset").classed("disabled", x3 === 0 && y3 === 0);
  }
  _resetOffset() {
    const imagery = this.context.systems.imagery;
    imagery.offset = [0, 0];
    this._updateValue();
  }
  _nudge(d2) {
    const imagery = this.context.systems.imagery;
    imagery.nudge(d2);
    this._updateValue();
  }
  _inputOffset(e3) {
    const imagery = this.context.systems.imagery;
    const $input = select_default2(e3.target);
    let val = $input.node().value;
    if (val === "")
      return this._resetOffset();
    val = val.replace(/;/g, ",").split(",").map((n3) => {
      return !isNaN(n3) && n3;
    });
    if (val.length !== 2 || !val[0] || !val[1]) {
      $input.classed("error", true);
      return;
    }
    imagery.offset = geoMetersToOffset(val);
    this._updateValue();
  }
  _pointerdown(e3) {
    const context2 = this.context;
    if (e3.button !== 0)
      return;
    const input = context2.container().selectAll(".nudge-inner-rect > input").node();
    if (e3.target === input)
      return;
    let origin = [e3.clientX, e3.clientY];
    const pointerId = e3.pointerId || "mouse";
    context2.container().append("div").attr("class", "nudge-surface");
    const pointermove = (e4) => {
      if (pointerId !== (e4.pointerId || "mouse"))
        return;
      const latest = [e4.clientX, e4.clientY];
      const delta = [
        -(origin[0] - latest[0]) / 4,
        -(origin[1] - latest[1]) / 4
      ];
      origin = latest;
      this._nudge(delta);
    };
    const pointerup = (e4) => {
      if (pointerId !== (e4.pointerId || "mouse"))
        return;
      if (e4.button !== 0)
        return;
      context2.container().selectAll(".nudge-surface").remove();
      select_default2(window).on(".drag-bg-offset", null);
    };
    select_default2(window).on("pointermove.drag-bg-offset", pointermove).on("pointerup.drag-bg-offset", pointerup).on("pointercancel.drag-bg-offset", pointerup);
  }
  renderDisclosureContent($selection) {
    const l10n = this.context.systems.l10n;
    let $container = $selection.selectAll(".nudge-container").data([0]);
    const $$container = $container.enter().append("div").attr("class", "nudge-container");
    $$container.append("div").attr("class", "nudge-instructions");
    const $$nudgeWrap = $$container.append("div").attr("class", "nudge-controls-wrap");
    const $$nudge = $$nudgeWrap.append("div").attr("class", "nudge-outer-rect").on("pointerdown", this._pointerdown);
    $$nudge.append("div").attr("class", "nudge-inner-rect").append("input").attr("type", "text").on("change", this._inputOffset);
    $$nudgeWrap.append("div").selectAll("button").data(DIRECTIONS).enter().append("button").attr("class", (d2) => `${d2[0]} nudge`).attr("tabindex", -1).on("click", (e3, d2) => this._nudge(d2[1]));
    $$nudgeWrap.append("button").attr("class", "nudge-reset disabled").on("click", (e3) => {
      e3.preventDefault();
      this._resetOffset();
    }).call(uiIcon("#rapid-icon-" + (l10n.isRTL ? "redo" : "undo")));
    $container = $container.merge($$container);
    $container.select(".nudge-instructions").text(l10n.t("background.offset"));
    $container.select(".nudge-reset").attr("title", l10n.t("background.reset"));
    this._updateValue();
  }
}

