// modules/ui/intro/UiIntro.ts
var chapterUi = {
  welcome: UiIntroWelcome,
  navigation: UiIntroNavigation,
  point: UiIntroPoint,
  area: UiIntroArea,
  line: UiIntroLine,
  building: UiIntroBuilding,
  rapid: UiIntroRapid,
  startEditing: UiIntroStartEditing
};
var chapterFlow = [
  "welcome",
  "navigation",
  "point",
  "area",
  "line",
  "building",
  "rapid",
  "startEditing"
];

class UiIntro {
  context;
  _introGraph;
  _rapidGraph;
  _original;
  _resume;
  _progress;
  _currChapter;
  Curtain;
  $buttons;
  $navwrap;
  constructor(context2) {
    this.context = context2;
    this._introGraph = {};
    this._rapidGraph = {};
    this._original = {};
    this._resume = {};
    this._progress = [];
    this._currChapter = null;
    this.Curtain = null;
    this.$buttons = null;
    this.$navwrap = null;
    this.start = this.start.bind(this);
    this._enterChapter = this._enterChapter.bind(this);
  }
  start(skipToRapid = false) {
    const context2 = this.context;
    const assets = context2.systems.assets;
    Promise.all([
      assets.loadAssetAsync("intro_rapid_graph"),
      assets.loadAssetAsync("intro_graph")
    ]).then((values) => {
      const rapidData = values[0].introRapidGraph;
      const introData = values[1].introGraph;
      for (const [id, data] of Object.entries(rapidData)) {
        if (!this._rapidGraph[id]) {
          this._rapidGraph[id] = createOsmEntity(context2, localize(context2, data));
        }
      }
      for (const [id, data] of Object.entries(introData)) {
        if (!this._introGraph[id]) {
          this._introGraph[id] = createOsmEntity(context2, localize(context2, data));
        }
      }
      this._startIntro(skipToRapid);
    });
  }
  _startIntro(skipToRapid) {
    const context2 = this.context;
    const editor = context2.systems.editor;
    const imagery = context2.systems.imagery;
    const l10n = context2.systems.l10n;
    const mapwithai = context2.services.mapwithai;
    const osm = context2.services.osm;
    const rapid = context2.systems.rapid;
    const scene = context2.systems.gfx.scene;
    const settings = context2.systems.settings;
    const ui = context2.systems.ui;
    const urlhash = context2.systems.urlhash;
    const $container = context2.$container;
    this._resume = {
      urlhash: urlhash.pause(),
      osm: osm?.pause(),
      mapwithai: mapwithai?.pause()
    };
    $container.classed("inIntro", true);
    context2.inIntro = true;
    context2.enter("browse");
    this._original = {
      hash: window.location.hash,
      transform: context2.viewport.transform.props,
      brightness: imagery.brightness,
      baseLayer: imagery.baseLayerSource(),
      overlayLayers: imagery.overlayLayerSources(),
      layersEnabled: new Set,
      datasetsAdded: new Set(rapid.addedDatasetIDs),
      datasetsEnabled: new Set(rapid.enabledDatasetIDs),
      edits: editor.toJSON()
    };
    for (const [layerID, layer] of scene.layers) {
      if (layer.enabled) {
        this._original.layersEnabled.add(layerID);
      }
    }
    scene.onlyLayers(["background", "osm", "labels"]);
    rapid.removeDatasets(rapid.addedDatasetIDs);
    rapid.addDatasets("rapid_intro_graph");
    const introSource = imagery.getSourceByID("Bing");
    imagery.baseLayerSource(introSource);
    this._original.overlayLayers.forEach((d2) => imagery.toggleOverlayLayer(d2));
    imagery.brightness = 1;
    ui.Sidebar.expand(false);
    this.Curtain = new UiCurtain(context2);
    $container.call(this.Curtain.enable);
    settings?.set("ui.walkthrough.started", "yes");
    const storedProgress = settings?.get("ui.walkthrough.progress") || "";
    this._progress = storedProgress.split(";").filter(Boolean);
    const chapters = chapterFlow.map((chapterID, i2) => {
      const chapter = new chapterUi[chapterID](context2, this.Curtain);
      chapter.on("done", () => {
        this.$buttons.filter((d2) => d2.title === chapter.title).classed("finished", true);
        this._progress.push(chapterID);
        settings?.set("ui.walkthrough.progress", utilArrayUniq(this._progress).join(";"));
        if (i2 < chapterFlow.length - 1) {
          const nextID = chapterFlow[i2 + 1];
          $container.select(`button.chapter-${nextID}`).classed("next", true);
        } else {
          this._finish();
        }
      });
      return chapter;
    });
    this.$navwrap = $container.append("div").attr("class", "intro-nav-wrap fillD");
    this.$navwrap.append("svg").attr("class", "intro-nav-wrap-logo").append("use").attr("xlink:href", "#rapid-logo-walkthrough");
    const buttonwrap = this.$navwrap.append("div").attr("class", "joined").selectAll("button.chapter");
    this.$buttons = buttonwrap.data(chapters).enter().append("button").attr("class", (d2, i2) => `chapter chapter-${chapterFlow[i2]}`).on("click", this._enterChapter);
    this.$buttons.append("span").text((d2) => l10n.t(d2.title));
    this.$buttons.append("span").attr("class", "status").call(uiIcon(l10n.isRTL ? "#rapid-icon-backward" : "#rapid-icon-forward", "inline"));
    context2.resetAsync().then(() => {
      editor.merge(Object.values(this._introGraph));
      mapwithai?.merge("rapid_intro_graph", Object.values(this._rapidGraph));
      editor.setCheckpoint("initial");
      this._enterChapter(undefined, chapters[skipToRapid ? 6 : 0]);
    });
  }
  _enterChapter(e3, newChapter) {
    const context2 = this.context;
    if (this._currChapter)
      this._currChapter.exit();
    context2.enter("browse");
    this._currChapter = newChapter;
    this._currChapter.enter();
    this.$buttons.classed("next", false).classed("active", (d2) => d2.title === this._currChapter.title);
  }
  _finish() {
    const context2 = this.context;
    const editor = context2.systems.editor;
    const imagery = context2.systems.imagery;
    const map2 = context2.systems.map;
    const rapid = context2.systems.rapid;
    const scene = context2.systems.gfx.scene;
    const settings = context2.systems.settings;
    const incomplete = utilArrayDifference(chapterFlow, this._progress);
    if (!incomplete.length) {
      settings?.set("ui.walkthrough.completed", "yes");
    }
    rapid.removeDatasets("rapid_intro_graph");
    rapid.addDatasets(this._original.datasetsAdded);
    rapid.enableDatasets(this._original.datasetsEnabled);
    this.Curtain.disable();
    this.$navwrap.remove();
    for (const [layerID, layer] of scene.layers) {
      layer.enabled = this._original.layersEnabled.has(layerID);
    }
    imagery.baseLayerSource(this._original.baseLayer);
    this._original.overlayLayers.forEach((d2) => imagery.toggleOverlayLayer(d2));
    imagery.brightness = this._original.brightness;
    map2.transform(this._original.transform);
    window.location.replace(this._original.hash);
    context2.$container.classed("inIntro", false);
    context2.inIntro = false;
    this._resume.osm?.();
    this._resume.mapwithai?.();
    this._resume.urlhash();
    context2.resetAsync().then(() => {
      if (this._original.edits) {
        return editor.fromJSONAsync(this._original.edits);
      } else {
        return Promise.resolve();
      }
    });
  }
}

