class UiPaneHelp extends UiPane {
  _docs;
  _$content;
  _currIndex;
  constructor(context2) {
    super(context2, "help");
    const l10n = context2.systems.l10n;
    const help = l10n.t("text.help");
    this.key = l10n.t("shortcuts.command.toggle_help.key");
    this.label = help;
    this.description = help;
    this.iconName = "rapid-icon-help";
    this._$content = null;
    this._currIndex = 0;
    const rtl = l10n.isRTL ? "-rtl" : "";
    const replacements = {
      version: `**${context2.version}**`,
      rapidicon: `<svg class="icon pre-text rapid"><use xlink:href="#rapid-logo-rapid-wordmark${rtl}"></use></svg>`
    };
    this._docs = [];
    for (const [section, subsections] of DOC_SECTIONS) {
      const markdown = subsections.reduce((acc, subsection) => {
        const stringID = `help.${section}.${subsection}`;
        const depth = HEADINGS[stringID];
        const hhh = depth ? Array(depth + 1).join("#") + " " : "";
        return acc + hhh + helpHtml(context2, stringID, replacements) + `

`;
      }, "");
      this._docs.push({
        title: l10n.t(`help.${section}.title`),
        contentHtml: f2.parse(markdown.trim()).replace(/<code>/g, "<kbd>").replace(/<\/code>/g, "</kbd>")
      });
    }
    this._clickChapter = this._clickChapter.bind(this);
    this._clickWalkthrough = this._clickWalkthrough.bind(this);
    this._clickShortcuts = this._clickShortcuts.bind(this);
  }
  renderContent($selection) {
    const context2 = this.context;
    const l10n = context2.systems.l10n;
    this._$content = $selection;
    const $$toc = $selection.selectAll(".toc").data([0]).enter().append("ul").attr("class", "toc");
    $$toc.selectAll("li").data(this._docs).enter().append("li").append("a").attr("href", "#").text((d2) => d2.title).on("click", (e3, d2) => {
      e3.preventDefault();
      this._clickChapter(d2, this._docs.indexOf(d2));
    });
    const $$shortcuts = $$toc.append("li").attr("class", "shortcuts").call(new UiTooltip(context2).title(l10n.t("shortcuts.tooltip")).shortcut("?").placement("top").attach).append("a").attr("href", "#").on("click", this._clickShortcuts);
    $$shortcuts.append("div").attr("class", "shortcuts-title-text");
    const $$walkthrough = $$toc.append("li").attr("class", "walkthrough").append("a").attr("href", "#").on("click", this._clickWalkthrough);
    $$walkthrough.append("svg").attr("class", "logo logo-walkthrough").append("use").attr("xlink:href", "#rapid-logo-walkthrough");
    $$walkthrough.append("div").attr("class", "walkthrough-title-text");
    const $$wrap = $selection.selectAll(".help-content-wrap").data([0]).enter().append("div").attr("class", "help-content-wrap");
    $$wrap.append("div").attr("class", "help-content");
    $$wrap.append("div").attr("class", "nav");
    $selection.select(".shortcuts-title-text").text(l10n.t("shortcuts.title"));
    $selection.select(".walkthrough-title-text").text(l10n.t("splash.walkthrough"));
    this._clickChapter(this._docs[this._currIndex], this._currIndex);
  }
  _clickChapter(d2, i2) {
    const l10n = this.context.systems.l10n;
    if (!this._$content)
      return;
    this._currIndex = i2;
    const docs = this._docs;
    const isRTL = l10n.isRTL;
    this._$content.property("scrollTop", 0);
    const $helpPane = select_default2(this._$content.node().parentElement);
    $helpPane.selectAll(".pane-heading > h2").text(d2.title);
    const $content = this._$content.selectAll(".help-content");
    $content.html(d2.contentHtml);
    $content.selectAll("a").attr("target", "_blank");
    this._$content.selectAll(".toc > li").classed("selected", (item) => item === d2);
    const drawNext = ($selection) => {
      if (i2 === docs.length - 1)
        return;
      const $$nextLink = $selection.append("a").attr("href", "#").attr("class", "next").on("click", (e3) => {
        e3.preventDefault();
        this._clickChapter(docs[i2 + 1], i2 + 1);
      });
      $$nextLink.append("span").text(docs[i2 + 1].title).call(uiIcon(isRTL ? "#rapid-icon-backward" : "#rapid-icon-forward", "inline"));
    };
    const drawPrevious = ($selection) => {
      if (i2 === 0)
        return;
      const $$prevLink = $selection.append("a").attr("href", "#").attr("class", "previous").on("click", (e3) => {
        e3.preventDefault();
        this._clickChapter(docs[i2 - 1], i2 - 1);
      });
      $$prevLink.call(uiIcon(isRTL ? "#rapid-icon-forward" : "#rapid-icon-backward", "inline")).append("span").text(docs[i2 - 1].title);
    };
    const $nav = this._$content.selectAll(".nav");
    $nav.html("");
    if (isRTL) {
      $nav.call(drawNext).call(drawPrevious);
    } else {
      $nav.call(drawPrevious).call(drawNext);
    }
  }
  _clickWalkthrough(e3) {
    const context2 = this.context;
    const ui = context2.systems.ui;
    e3.preventDefault();
    if (context2.inIntro)
      return;
    new UiIntro(context2).start();
    ui?.togglePanes();
  }
  _clickShortcuts(e3) {
    const ui = this.context.systems.ui;
    e3.preventDefault();
    ui?.Shortcuts?.toggle();
  }
}
// modules/ui/sections/UiSectionValidationIssues.ts
var MAX_ISSUES = 1000;

class UiSectionValidationIssues extends AbstractUiSection {
  _severity;
  _issues;
  constructor(context2, severity) {
    super(context2, `issues-${severity}`);
    this._severity = severity;
    this._issues = [];
    this._drawIssuesList = this._drawIssuesList.bind(this);
    this._clickAutoFix = this._clickAutoFix.bind(this);
    this._clickAutoFixAll = this._clickAutoFixAll.bind(this);
    this._renderWhenIdle = this._renderWhenIdle.bind(this);
    const gfx = context2.systems.gfx;
    const settings = context2.systems.settings;
    const scheduler = context2.systems.scheduler;
    const urlhash = context2.systems.urlhash;
    const validator = context2.systems.validator;
    settings?.on("settingschange", this._renderWhenIdle);
    validator?.on("validated", this._renderWhenIdle);
    urlhash?.on("hashchange", (currParams, prevParams) => {
      if (currParams.get("poweruser") !== prevParams.get("poweruser")) {
        this._renderWhenIdle();
      }
    });
    gfx.on("draw", () => {
      if (scheduler) {
        scheduler.debounce("ValidationIssues-render", this._renderWhenIdle, { ms: 500 });
      } else {
        this._renderWhenIdle();
      }
    });
  }
  label() {
    const l10n = this.context.systems.l10n;
    const n3 = this._issues.length;
    const count2 = n3 > MAX_ISSUES ? `>${MAX_ISSUES}` : String(n3);
    const title = l10n.t(`text.${this._severity}`, { n: n3 });
    return l10n.t("inspector.title_count", { title, count: count2 });
  }
  shouldDisplay() {
    return this._issues.length > 0;
  }
  renderDisclosureContent($selection) {
    const editor = this.context.systems.editor;
    const viewport = this.context.viewport;
    const graph = editor.staging.graph;
    const centerLoc = viewport.centerLoc();
    let issues = this._issues.map(function withDistance(issue) {
      const extent = issue.extent(graph);
      const dist = extent ? geoSphericalDistance(centerLoc, extent.center()) : 0;
      return Object.assign(issue, { dist });
    }).sort((a2, b3) => a2.dist - b3.dist);
    issues = issues.slice(0, MAX_ISSUES);
    $selection.call(this._drawIssuesList, issues);
  }
  _drawIssuesList($selection, issues) {
    const context2 = this.context;
    const l10n = context2.systems.l10n;
    const settings = context2.systems.settings;
    const validator = context2.systems.validator;
    const severity = this._severity;
    const showAutoFix = settings?.get("poweruser.showAutoFix") === "true";
    let $list = $selection.selectAll(".issues-list").data([0]);
    $list = $list.enter().append("ul").attr("class", `layer-list issues-list ${severity}-list`).merge($list);
    let $items = $list.selectAll("li").data(issues, (d2) => d2.key);
    $items.exit().remove();
    const $$items = $items.enter().append("li").attr("class", (d2) => `issue severity-${d2.severity}`);
    const $$labels = $$items.append("button").attr("class", "issue-label").on("click", (e3, d2) => validator.focusIssue(d2)).on("mouseover", (e3, d2) => utilHighlightEntities(context2, d2.entityIds, true)).on("mouseout", (e3, d2) => utilHighlightEntities(context2, d2.entityIds, false));
    const $$text = $$labels.append("span").attr("class", "issue-text");
    $$text.append("span").attr("class", "issue-icon").each((d2, i2, nodes) => {
      select_default2(nodes[i2]).call(uiIcon(validator.getSeverityIcon(d2.severity)));
    });
    $$text.append("span").attr("class", "issue-message");
    $$labels.append("span").attr("class", "issue-autofix").append("button").attr("title", l10n.t("issues.fix_one.title")).attr("class", "autofix action").on("click", this._clickAutoFix).call(uiIcon("#rapid-icon-wrench"));
    $items = $items.merge($$items).order();
    $items.selectAll(".issue-message").text((d2) => d2.message(context2));
    $items.selectAll(".issue-autofix").classed("hide", (d2) => !(showAutoFix && d2.autoArgs));
    const autofixable = issues.filter((issue) => issue.autoArgs);
    let $autoFixAll = $selection.selectAll(".autofix-all").data(showAutoFix && autofixable.length ? [0] : []);
    $autoFixAll.exit().remove();
    const $$autoFixAll = $autoFixAll.enter().insert("div", ".issues-list").attr("class", "autofix-all");
    const $$link = $$autoFixAll.append("a").attr("class", "autofix-all-link").attr("href", "#");
    $$link.append("span").attr("class", "autofix-all-link-text");
    $$link.append("span").attr("class", "autofix-all-link-icon").call(uiIcon("#rapid-icon-wrench"));
    $autoFixAll = $autoFixAll.merge($$autoFixAll);
    $autoFixAll.selectAll(".autofix-all-link-text").text(l10n.t("issues.fix_all.title"));
    $autoFixAll.selectAll(".autofix-all-link").on("click", (e3) => this._clickAutoFixAll(e3, autofixable));
  }
  _clickAutoFix(e3, issue) {
    const editor = this.context.systems.editor;
    if (e3) {
      e3.preventDefault();
      e3.stopPropagation();
    }
    utilHighlightEntities(this.context, issue.entityIds, false);
    editor.perform(issue.autoArgs[0]);
    editor.commit({ annotation: issue.autoArgs[1], selectedIDs: issue.entityIds });
  }
  _clickAutoFixAll(e3, issues) {
    const context2 = this.context;
    const editor = context2.systems.editor;
    const l10n = context2.systems.l10n;
    e3.preventDefault();
    e3.stopPropagation();
    editor.beginTransaction();
    for (const issue of issues) {
      const action = issue.autoArgs[0];
      editor.perform(action);
    }
    editor.commit({ annotation: l10n.t("issues.fix_all.annotation") });
    editor.endTransaction();
  }
  _getOptions() {
    const settings = this.context.systems.settings;
    return {
      what: settings?.get("validator.what") || "edited",
      where: settings?.get("validator.where") || "all"
    };
  }
  _reloadIssues() {
    const validator = this.context.systems.validator;
    const options = this._getOptions();
    const issuesBySeverity = validator.getIssuesBySeverity(options);
    this._issues = issuesBySeverity[this._severity];
  }
  _isVisible() {
    return this.context.container().selectAll(".map-panes .issues-pane.shown").size();
  }
  _renderWhenIdle() {
    const scheduler = this.context.systems.scheduler;
    const fn = () => {
      if (!this._isVisible())
        return;
      this._reloadIssues();
      this.renderInner();
    };
    if (scheduler) {
      scheduler.scheduleIdleTask(fn).catch((err) => {
        if (err?.name === "AbortError")
          return;
        console.error(err);
      });
    } else {
      fn();
    }
  }
}

// modules/ui/sections/UiSectionValidationOptions.ts
class UiSectionValidationOptions extends AbstractUiSection {
  constructor(context2) {
    super(context2, "issues-options");
    this._isChecked = this._isChecked.bind(this);
    this._setOptionValue = this._setOptionValue.bind(this);
  }
  renderContent($selection) {
    const context2 = this.context;
    const l10n = context2.systems.l10n;
    let $wrap = $selection.selectAll(".issues-options-container").data([0]);
    $wrap = $wrap.enter().append("div").attr("class", "issues-options-container").merge($wrap);
    const fields = [
      { key: "what", values: ["edited", "all"] },
      { key: "where", values: ["visible", "all"] }
    ];
    let $options = $wrap.selectAll(".issues-option").data(fields, (d2) => d2.key);
    const $$options = $options.enter().append("div").attr("class", (d2) => `issues-option issues-option-${d2.key}`);
    $$options.append("div").attr("class", "issues-option-title");
    const $$labels = $$options.selectAll("label").data((d2) => d2.values.map((val) => ({ key: d2.key, value: val }))).enter().append("label");
    $$labels.append("input").attr("type", "radio").attr("name", (d2) => `issues-option-${d2.key}`).attr("value", (d2) => d2.value).property("checked", this._isChecked).on("change", this._setOptionValue);
    $$labels.append("span");
    $options = $options.merge($$options);
    $options.selectAll(".issues-option-title").text((d2) => l10n.t(`issues.options.${d2.key}.title`));
    $options.selectAll("label span").text((d2) => l10n.t(`issues.options.${d2.key}.${d2.value}`));
  }
  _isChecked(d2) {
    const settings = this.context.systems.settings;
    const whatVal = settings?.get("validator.what") || "edited";
    const whereVal = settings?.get("validator.where") || "all";
    return d2.key === "what" ? d2.value === whatVal : d2.key === "where" ? d2.value === whereVal : false;
  }
  _setOptionValue(e3, d2) {
    const settings = this.context.systems.settings;
    const val = e3.target.value;
    settings?.set(`validator.${d2.key}`, val);
  }
}

