// modules/ui/sections/UiSectionValidationStatus.ts
class UiSectionValidationStatus extends AbstractUiSection {
  constructor(context2) {
    super(context2, "issues-status");
    this._renderWhenIdle = this._renderWhenIdle.bind(this);
    const gfx = context2.systems.gfx;
    const scheduler = context2.systems.scheduler;
    const settings = context2.systems.settings;
    const validator = context2.systems.validator;
    settings?.on("settingschange", this._renderWhenIdle);
    validator.on("validated", this._renderWhenIdle);
    gfx.on("draw", () => {
      if (scheduler) {
        scheduler.debounce("ValidationStatus-render", this._renderWhenIdle, { ms: 1000 });
      } else {
        this._renderWhenIdle();
      }
    });
  }
  shouldDisplay() {
    const validator = this.context.systems.validator;
    const issues = validator.getIssues(this._getOptions());
    return issues.length === 0;
  }
  _getOptions() {
    const settings = this.context.systems.settings;
    return {
      what: settings?.get("validator.what") || "edited",
      where: settings?.get("validator.where") || "all"
    };
  }
  renderContent($selection) {
    const $box = $selection.selectAll(".box").data([0]);
    const $$box = $box.enter().append("div").attr("class", "box");
    $$box.append("div").call(uiIcon("#rapid-icon-apply", "pre-text"));
    const $$noIssuesMessage = $$box.append("span");
    $$noIssuesMessage.append("strong").attr("class", "message");
    $$noIssuesMessage.append("br");
    $$noIssuesMessage.append("span").attr("class", "details");
    this._renderIgnoredIssuesReset($selection);
    this._setNoIssuesText($selection);
  }
  _renderIgnoredIssuesReset($selection) {
    const l10n = this.context.systems.l10n;
    const validator = this.context.systems.validator;
    const ignoredIssues = validator.getIssues({ what: "all", where: "all", includeDisabledRules: true, includeIgnored: "only" });
    let $resetIgnored = $selection.selectAll(".reset-ignored").data(ignoredIssues.length ? [0] : []);
    $resetIgnored.exit().remove();
    const $$resetIgnored = $resetIgnored.enter().append("div").attr("class", "reset-ignored section-footer");
    $$resetIgnored.append("a").attr("href", "#");
    $resetIgnored = $resetIgnored.merge($$resetIgnored);
    $resetIgnored.select("a").text(l10n.t("inspector.title_count", { title: l10n.t("issues.reset_ignored"), count: ignoredIssues.length }));
    $resetIgnored.on("click", (e3) => {
      e3.preventDefault();
      validator.resetIgnoredIssues();
    });
  }
  _setNoIssuesText($selection) {
    const context2 = this.context;
    const l10n = context2.systems.l10n;
    const validator = context2.systems.validator;
    const opts = this._getOptions();
    function checkForHiddenIssues(cases) {
      for (const type in cases) {
        const hiddenOpts = cases[type];
        const hiddenIssues = validator.getIssues(hiddenOpts);
        if (hiddenIssues.length) {
          $selection.select(".box .details").text(l10n.t("issues.no_issues.hidden_issues." + type, { count: hiddenIssues.length.toString() }));
          return;
        }
      }
      $selection.select(".box .details").text(l10n.t("issues.no_issues.hidden_issues.none"));
    }
    let messageType;
    if (opts.what === "edited" && opts.where === "visible") {
      messageType = "edits_in_view";
      checkForHiddenIssues({
        elsewhere: { what: "edited", where: "all" },
        everything_else: { what: "all", where: "visible" },
        disabled_rules: { what: "edited", where: "visible", includeDisabledRules: "only" },
        everything_else_elsewhere: { what: "all", where: "all" },
        disabled_rules_elsewhere: { what: "edited", where: "all", includeDisabledRules: "only" },
        ignored_issues: { what: "edited", where: "visible", includeIgnored: "only" },
        ignored_issues_elsewhere: { what: "edited", where: "all", includeIgnored: "only" }
      });
    } else if (opts.what === "edited" && opts.where === "all") {
      messageType = "edits";
      checkForHiddenIssues({
        everything_else: { what: "all", where: "all" },
        disabled_rules: { what: "edited", where: "all", includeDisabledRules: "only" },
        ignored_issues: { what: "edited", where: "all", includeIgnored: "only" }
      });
    } else if (opts.what === "all" && opts.where === "visible") {
      messageType = "everything_in_view";
      checkForHiddenIssues({
        elsewhere: { what: "all", where: "all" },
        disabled_rules: { what: "all", where: "visible", includeDisabledRules: "only" },
        disabled_rules_elsewhere: { what: "all", where: "all", includeDisabledRules: "only" },
        ignored_issues: { what: "all", where: "visible", includeIgnored: "only" },
        ignored_issues_elsewhere: { what: "all", where: "all", includeIgnored: "only" }
      });
    } else if (opts.what === "all" && opts.where === "all") {
      messageType = "everything";
      checkForHiddenIssues({
        disabled_rules: { what: "all", where: "all", includeDisabledRules: "only" },
        ignored_issues: { what: "all", where: "all", includeIgnored: "only" }
      });
    }
    if (opts.what === "edited" && context2.systems.editor.difference().summary().size === 0) {
      messageType = "no_edits";
    }
    $selection.select(".box .message").text(l10n.t(`issues.no_issues.message.${messageType}`));
  }
  _renderWhenIdle() {
    const scheduler = this.context.systems.scheduler;
    if (scheduler) {
      scheduler.scheduleIdleTask(this.renderInner).catch((err) => {
        if (err?.name === "AbortError")
          return;
        console.error(err);
      });
    } else {
      this.renderInner();
    }
  }
}

