// modules/ui/sections/UiSectionPhotoOverlays.ts
class UiSectionPhotoOverlays extends AbstractUiSection {
  constructor(context2) {
    super(context2, "photo-overlays");
    const photos = context2.systems.photos;
    const scene = context2.systems.gfx.scene;
    this._drawPhotoItems = this._drawPhotoItems.bind(this);
    this._drawPhotoTypeItems = this._drawPhotoTypeItems.bind(this);
    this._drawDateFilter = this._drawDateFilter.bind(this);
    scene.on("layerchange", this.renderInner);
    photos.on("photochange", this.renderInner);
  }
  label() {
    const l10n = this.context.systems.l10n;
    return l10n.t("photo_overlays.title");
  }
  renderDisclosureContent($selection) {
    const photos = this.context.systems.photos;
    const $container = $selection.selectAll(".photo-overlay-container").data(photos ? [0] : []);
    $container.exit().remove();
    $container.enter().append("div").attr("class", "photo-overlay-container").merge($container).call(this._drawPhotoItems).call(this._drawPhotoTypeItems).call(this._drawDateFilter);
  }
  _setLayer(layerID, val) {
    const context2 = this.context;
    const scene = context2.systems.gfx.scene;
    const mode = context2.mode;
    if (mode && /^draw/.test(mode.id))
      return;
    if (val) {
      scene.enableLayers(layerID);
    } else {
      scene.disableLayers(layerID);
    }
  }
  _toggleLayer(layerID) {
    const photos = this.context.systems.photos;
    this._setLayer(layerID, !photos.isLayerEnabled(layerID));
  }
  _drawPhotoItems($selection) {
    const context2 = this.context;
    const l10n = context2.systems.l10n;
    const photos = context2.systems.photos;
    const scene = context2.systems.gfx.scene;
    const items = [];
    for (const layerID of photos.layerIDs) {
      const layer = scene.layers.get(layerID);
      if (layer?.supported) {
        items.push(layer);
      }
    }
    let $ul = $selection.selectAll(".layer-list-photos").data([0]);
    $ul = $ul.enter().append("ul").attr("class", "layer-list layer-list-photos").merge($ul);
    const $li = $ul.selectAll(".list-item-photos").data(items);
    $li.exit().remove();
    const $$li = $li.enter().append("li").attr("class", (d2) => {
      let classes = `list-item-photos list-item-${d2.id}`;
      if (photos.detectionLayerIDs.includes(d2.id)) {
        classes += " indented";
      }
      return classes;
    });
    const $$label = $$li.append("label").each((d2, i2, nodes) => {
      const stringID = d2.id.replace(/-/g, "_") + ".tooltip";
      select_default2(nodes[i2]).call(new UiTooltip(context2).title(l10n.t(stringID)).placement("top").attach);
    });
    $$label.append("input").attr("type", "checkbox").on("change", (e3, d2) => this._toggleLayer(d2.id));
    $$label.append("span").text((d2) => {
      const stringID = d2.id.replace(/-/g, "_") + ".title";
      return l10n.t(stringID);
    });
    $li.merge($$li).classed("active", (d2) => d2.enabled).selectAll("input").property("checked", (d2) => d2.enabled);
  }
  _drawPhotoTypeItems($selection) {
    const context2 = this.context;
    const l10n = context2.systems.l10n;
    const photos = context2.systems.photos;
    const photoTypes = photos.photoTypes;
    function isTypeEnabled(d2) {
      return photos.showsPhotoType(d2);
    }
    let $ul = $selection.selectAll(".layer-list-photo-types").data([0]);
    $ul.exit().remove();
    $ul = $ul.enter().append("ul").attr("class", "layer-list layer-list-photo-types").merge($ul);
    const $li = $ul.selectAll(".list-item-photo-types").data(photos.shouldFilterByPhotoType() ? photoTypes : []);
    $li.exit().remove();
    const $$li = $li.enter().append("li").attr("class", (d2) => `list-item-photo-types list-item-${d2}`);
    const $$label = $$li.append("label").each((d2, i2, nodes) => {
      select_default2(nodes[i2]).call(new UiTooltip(context2).title(l10n.t(`photo_overlays.photo_type.${d2}.tooltip`)).placement("top").attach);
    });
    $$label.append("input").attr("type", "checkbox").on("change", (e3, d2) => photos.togglePhotoType(d2));
    $$label.append("span").text((d2) => l10n.t(`photo_overlays.photo_type.${d2}.title`));
    $li.merge($$li).classed("active", isTypeEnabled).selectAll("input").property("checked", isTypeEnabled);
  }
  _drawDateFilter($selection) {
    const context2 = this.context;
    const l10n = context2.systems.l10n;
    const photos = context2.systems.photos;
    const dateFilterTypes = photos.dateFilters;
    function isFilterEnabled(d2) {
      return !!photos.dateFilterValue(d2);
    }
    let $ul = $selection.selectAll(".layer-list-date-filter").data([0]);
    $ul.exit().remove();
    $ul = $ul.enter().append("ul").attr("class", "layer-list layer-list-date-filter").merge($ul);
    let $li = $ul.selectAll(".list-item-date-filter").data(photos.shouldFilterByDate() ? dateFilterTypes : []);
    $li.exit().remove();
    const $$li = $li.enter().append("li").attr("class", "list-item-date-filter");
    const $$label = $$li.append("label").each((d2, i2, nodes) => {
      select_default2(nodes[i2]).call(new UiTooltip(context2).title(l10n.t(`photo_overlays.date_filter.${d2}.tooltip`)).placement("top").attach);
    });
    $$label.append("span").text((d2) => l10n.t(`photo_overlays.date_filter.${d2}.title`));
    $$label.append("input").attr("type", "date").attr("class", "list-item-input").attr("placeholder", l10n.t("units.year_month_day")).call(utilNoAuto).each((d2, i2, nodes) => {
      utilGetSetValue(select_default2(nodes[i2]), photos.dateFilterValue(d2) || "");
    }).on("change", (e3, d2) => {
      const value = utilGetSetValue(select_default2(e3.currentTarget)).trim();
      photos.setDateFilter(d2, value);
      $li.selectAll("input").each((d3, i2, nodes) => {
        utilGetSetValue(select_default2(nodes[i2]), photos.dateFilterValue(d3) || "");
      });
    });
    $li = $li.merge($$li).classed("active", isFilterEnabled);
  }
}

