// modules/ui/UiPresetIcon.ts
class UiPresetIcon {
  context;
  _preset;
  _geometry;
  constructor(context2) {
    this.context = context2;
    this._preset = null;
    this._geometry = null;
    this.render = this.render.bind(this);
  }
  preset(val) {
    if (!arguments.length)
      return this._preset;
    this._preset = val ?? null;
    return this;
  }
  geometry(val) {
    if (!arguments.length)
      return this._geometry;
    this._geometry = val ?? null;
    return this;
  }
  _getIcon(p2, geom2) {
    if (Array.isArray(p2))
      return "rapid-icon-data";
    if (p2?.props?.icon)
      return p2.props.icon;
    if (geom2 === "line")
      return "rapid-other-line";
    if (geom2 === "vertex")
      return p2?.isFallback() ? "" : "temaki-vertex";
    return "maki-marker-stroked";
  }
  _renderCategoryBorder($container, style) {
    const px = 60;
    const color2 = new Color(style.fill.color).toHex();
    const opacity = style.fill.opacity;
    const FOLDER_PATH = "M9.5,7.5 L25.5,7.5 L28.5,12.5 L49.5,12.5 C51.709139,12.5 53.5,14.290861 53.5,16.5 L53.5,43.5 C53.5,45.709139 51.709139,47.5 49.5,47.5 L10.5,47.5 C8.290861,47.5 6.5,45.709139 6.5,43.5 L6.5,12.5 L9.5,7.5 Z";
    $container.append("svg").attr("class", "preset-icon-category-border").attr("width", `${px}px`).attr("height", `${px}px`).attr("viewBox", `0 0 ${px} ${px}`).append("path").attr("fill", color2).attr("fill-opacity", opacity ?? null).attr("stroke", color2).attr("d", FOLDER_PATH);
  }
  _renderPointBorder($container) {
    const px = 60;
    const PIN_PATH = "M 0,0 C -2,-2 -8,-10 -8,-15 C -8,-19 -4,-23 0,-23 C 4,-23 8,-19 8,-15 C 8,-10 2,-2 0,0 Z";
    $container.append("svg").attr("class", "preset-icon-point-border").attr("width", `${px}px`).attr("height", `${px}px`).attr("viewBox", "-10 -27 20 30").append("path").attr("d", PIN_PATH);
  }
  _renderVertexBorder($container) {
    const px = 60;
    const mid = px / 2;
    const d2 = px * 2 / 3;
    $container.append("svg").attr("class", "preset-icon-vertex-border").attr("width", `${px}px`).attr("height", `${px}px`).attr("viewBox", `0 0 ${px} ${px}`).append("circle").attr("cx", mid).attr("cy", mid).attr("r", d2 / 2);
  }
  _renderAreaBorder($container, style) {
    const px = 60;
    const mid = px / 2;
    const len = px * 2 / 3;
    const c1 = (px - len) / 2;
    const c2 = c1 + len;
    const color2 = new Color(style.fill.color).toHex();
    const opacity = style.fill.opacity;
    const $svg = $container.append("svg").attr("class", "preset-icon-area-border").attr("width", `${px}px`).attr("height", `${px}px`).attr("viewBox", `0 0 ${px} ${px}`);
    $svg.append("path").attr("fill", color2).attr("fill-opacity", opacity ?? null).attr("stroke", color2).attr("d", `M${c1} ${c1} L${c1} ${c2} L${c2} ${c2} L${c2} ${c1} Z`);
    const rVertex = 2.5;
    [[c1, c1], [c1, c2], [c2, c2], [c2, c1]].forEach(([cx, cy]) => {
      $svg.append("circle").attr("class", "vertex").attr("cx", cx).attr("cy", cy).attr("r", rVertex);
    });
    const rMidpoint = 1.25;
    [[c1, mid], [c2, mid], [mid, c1], [mid, c2]].forEach(([cx, cy]) => {
      $svg.append("circle").attr("class", "midpoint").attr("cx", cx).attr("cy", cy).attr("r", rMidpoint);
    });
  }
  _renderLine($container, style) {
    const px = 60;
    const y3 = Math.round(px * 0.72);
    const l4 = Math.round(px * 0.6);
    const x1 = (px - l4) / 2;
    const x22 = x1 + l4;
    const casingColor = new Color(style.casing.color).toHex();
    const strokeColor = new Color(style.stroke.color).toHex();
    const dash = style.stroke.dash;
    const hasDash = Array.isArray(dash);
    const $svg = $container.append("svg").attr("class", "preset-icon-line").attr("width", `${px}px`).attr("height", `${px}px`).attr("viewBox", `0 0 ${px} ${px}`);
    $svg.append("path").attr("class", "casing").attr("stroke", casingColor).attr("stroke-opacity", hasDash ? 1 : 0.5).attr("d", `M${x1} ${y3} L${x22} ${y3}`);
    $svg.append("path").attr("class", "stroke").attr("stroke", strokeColor).attr("stroke-dasharray", hasDash ? dash.map((v3) => v3 * 0.75).join(" ") : null).attr("d", `M${x1} ${y3} L${x22} ${y3}`);
    const rVertex = 3;
    [[x1 - 1, y3], [x22 + 1, y3]].forEach(([cx, cy]) => {
      $svg.append("circle").attr("class", "vertex").attr("cx", cx).attr("cy", cy).attr("r", rVertex);
    });
  }
  _renderRoute($container) {
    $container.append("div").attr("class", "preset-icon-route").call(uiIcon("#rapid-route", "rapid-icon lowered"));
  }
  _renderSvgIcon($container, iconName, klass, color2) {
    $container.append("div").attr("class", "preset-icon").call(uiIcon(`#${iconName}`, klass.join(" ")));
    $container.selectAll(".preset-icon svg.icon").attr("color", color2);
  }
  _renderImageIcon($container, imageURL) {
    $container.selectAll("img.image-icon").data([imageURL]).enter().append("img").attr("class", "image-icon").attr("src", imageURL).on("load", () => $container.classed("showing-img", true)).on("error", () => $container.classed("showing-img", false));
  }
  render($selection) {
    const context2 = this.context;
    let $container = $selection.selectAll(".preset-icon-container").data([0]);
    $container = $container.enter().append("div").attr("class", "preset-icon-container").merge($container).html("");
    const p2 = this._preset;
    let geom2 = this._geometry;
    if (!p2 || !geom2)
      return;
    const isMulti = Array.isArray(p2);
    const isPreset = !isMulti && typeof p2.setTags === "function";
    const isCategory = !isMulti && !isPreset;
    const tags = isPreset ? p2.setTags({}, geom2) : {};
    for (const k3 in tags) {
      if (tags[k3] === "*") {
        tags[k3] = "yes";
      }
    }
    if (geom2 === "relation" && (tags.type === "route" || tags.type === "waterway")) {
      geom2 = "route";
    }
    const settings = context2.systems.settings;
    const styles = context2.systems.styles;
    const showThirdPartyIcons = (settings?.get("ui.privacy.thirdPartyIcons") ?? "true") === "true";
    const imageURL = showThirdPartyIcons && p2?.props?.imageURL;
    const picon = this._getIcon(p2, geom2);
    const showVertex = isPreset && geom2 === "vertex";
    const showLine = isPreset && geom2 === "line";
    const showArea = isPreset && geom2 === "area";
    const showRoute = isPreset && geom2 === "route" && p2.id !== "type/route";
    const style = styles.styleMatch(tags, this._geometry, "osm");
    $container.classed("showing-img", !!imageURL);
    if (isCategory)
      this._renderCategoryBorder($container, style);
    if (showVertex)
      this._renderVertexBorder($container);
    if (showArea)
      this._renderAreaBorder($container, style);
    if (showLine)
      this._renderLine($container, style);
    if (showRoute)
      this._renderRoute($container);
    if (picon) {
      const isRaised = showLine || showRoute;
      const isShrunk = isMulti || isCategory || showLine || showRoute;
      const isRapidIcon = /^rapid-/.test(picon);
      const klass = [];
      if (isRapidIcon)
        klass.push("rapid-icon");
      if (isShrunk)
        klass.push("shrunk");
      if (isRaised)
        klass.push("raised");
      let color2 = "#333";
      if (showLine || showRoute) {
        if (isRapidIcon) {
          color2 = new Color(style.stroke.color).toHex();
        }
      }
      this._renderSvgIcon($container, picon, klass, color2);
    }
    if (imageURL) {
      this._renderImageIcon($container, imageURL);
    }
  }
}

