// modules/ui/UiFormFields.ts
class UiFormFields {
  context;
  fieldsArr;
  state;
  klass;
  $parent;
  _moreCombo;
  _lastPlaceholder;
  constructor(context2) {
    this.context = context2;
    this.$parent = null;
    this.fieldsArr = [];
    this.state = "";
    this.klass = "";
    this._moreCombo = new UiCombobox(context2, "more-fields").minItems(1);
    this._lastPlaceholder = "";
    this.render = this.render.bind(this);
  }
  render($parent = this.$parent) {
    if ($parent instanceof selection_default) {
      this.$parent = $parent;
    } else {
      return;
    }
    const context2 = this.context;
    const l10n = context2.systems.l10n;
    const allowedFields = this.fieldsArr.filter((uifield) => uifield.isAllowed());
    const shown = allowedFields.filter((uifield) => uifield.isShown());
    const notShown = allowedFields.filter((uifield) => !uifield.isShown());
    let $container = $parent.selectAll(".form-fields-container").data([0]);
    $container = $container.enter().append("div").attr("class", "form-fields-container " + (this.klass || "")).merge($container);
    let $fields = $container.selectAll(".wrap-form-field").data(shown, (d2) => d2.id + (d2.entityIDs ? d2.entityIDs.join() : ""));
    $fields.exit().remove();
    const $$fields = $fields.enter().append("div").attr("class", (d2) => `wrap-form-field wrap-form-field-${d2.safeid}`);
    $fields = $fields.merge($$fields);
    $fields.order().each((d2, i2, nodes) => {
      select_default2(nodes[i2]).call(d2.render);
    });
    const labels = [];
    const moreFields = notShown.map((uifield) => {
      const label = uifield.label;
      labels.push(label);
      let terms = uifield.terms;
      if (uifield.key)
        terms.push(uifield.key);
      if (uifield.keys)
        terms = terms.concat(uifield.keys);
      return {
        display: uifield.label,
        value: label,
        title: label,
        field: uifield,
        terms
      };
    });
    const placeholder = labels.slice(0, 3).join(", ") + (labels.length > 3 ? "…" : "");
    let $more = $parent.selectAll(".more-fields").data(this.state === "hover" || moreFields.length === 0 ? [] : [0]);
    $more.exit().remove();
    const $$more = $more.enter().append("div").attr("class", "more-fields").append("label");
    $$more.append("span").text(l10n.t("inspector.add_fields"));
    $more = $more.merge($$more);
    let $input = $more.selectAll(".value").data([0]);
    $input.exit().remove();
    $input = $input.enter().append("input").attr("class", "value").attr("type", "text").attr("placeholder", placeholder).call(utilNoAuto).merge($input);
    $input.call(utilGetSetValue, "").call(this._moreCombo.data(moreFields).on("accept", (d2) => {
      if (!d2)
        return;
      const uifield = d2.field;
      uifield.show();
      this.render();
      uifield.focus();
    }).attach);
    if (this._lastPlaceholder !== placeholder) {
      $input.attr("placeholder", placeholder);
      this._lastPlaceholder = placeholder;
    }
  }
}

// modules/ui/sections/UiSectionPresetFields.ts
class UiSectionPresetFields extends AbstractUiSection {
  FormFields;
  _state;
  _uifields;
  _presets;
  _tags;
  _entityIDs;
  constructor(context2) {
    super(context2, "preset-fields");
    this.FormFields = new UiFormFields(context2);
    this._state = undefined;
    this._uifields = null;
    this._presets = [];
    this._tags = undefined;
    this._entityIDs = [];
  }
  label() {
    const l10n = this.context.systems.l10n;
    return l10n.t("text.field", { n: 100 });
  }
  renderDisclosureContent($selection) {
    const context2 = this.context;
    const editor = context2.systems.editor;
    const l10n = context2.systems.l10n;
    const schema = context2.systems.schema;
    const scope = schema.getScope("osm");
    if (!this._uifields) {
      const graph = editor.staging.graph;
      const localeCode = l10n.localeCode;
      const allGeometries = new Set;
      for (const entityID of this._entityIDs) {
        const entity = graph.entity(entityID);
        const geometry = entity.geometry(graph);
        allGeometries.add(geometry);
      }
      let allFields = [];
      let allMoreFields = [];
      let sharedTotalFields;
      for (const preset of this._presets) {
        const fields = preset.fields();
        const moreFields = preset.moreFields();
        allFields = utilArrayUnion(allFields, fields);
        allMoreFields = utilArrayUnion(allMoreFields, moreFields);
        if (!sharedTotalFields) {
          sharedTotalFields = utilArrayUnion(fields, moreFields);
        } else {
          sharedTotalFields = sharedTotalFields.filter((field) => {
            return fields.includes(field) || moreFields.includes(field);
          });
        }
      }
      const sharedFields = allFields.filter((field) => sharedTotalFields.includes(field));
      const sharedMoreFields = allMoreFields.filter((field) => sharedTotalFields.includes(field));
      this._uifields = [];
      for (const field of sharedFields) {
        if (!allGeometries.isSubsetOf(field.geometries))
          continue;
        this._uifields.push(createUiField(context2, field, this._entityIDs));
      }
      const additionalFields = utilArrayUnion(sharedMoreFields, [...scope?.universal?.values() ?? []]);
      additionalFields.sort((field1, field2) => {
        return field1.label.localeCompare(field2.label, localeCode);
      });
      for (const field of additionalFields) {
        if (sharedFields.includes(field))
          continue;
        if (!allGeometries.isSubsetOf(field.geometries))
          continue;
        this._uifields.push(createUiField(context2, field, this._entityIDs, { show: false }));
      }
      const ids = this._entityIDs.slice();
      for (const UiField of this._uifields) {
        UiField.on("change", (t2, onInput) => {
          this.emit("change", ids, t2, onInput);
        });
        UiField.on("revert", (keys) => {
          this.emit("revert", keys);
        });
      }
    }
    for (const UiField of this._uifields) {
      UiField.state(this._state).tags(this._tags);
    }
    this.FormFields.fieldsArr = this._uifields;
    this.FormFields.state = this._state || "";
    this.FormFields.klass = "grouped-items-area";
    $selection.call(this.FormFields.render);
    $selection.selectAll(".wrap-form-field input").on("keydown", function(e3) {
      if (e3.keyCode === 13 && context2.container().select(".combobox").empty()) {
        context2.enter("browse");
      }
    });
  }
  presets(val) {
    if (!arguments.length)
      return this._presets;
    if (!this._presets || !val || !utilArrayIdentical(this._presets, val)) {
      this._presets = val ?? [];
      this._uifields = null;
    }
    return this;
  }
  state(val) {
    if (!arguments.length)
      return this._state;
    this._state = val;
    return this;
  }
  tags(val) {
    if (!arguments.length)
      return this._tags;
    this._tags = val;
    return this;
  }
  entityIDs(val) {
    if (!arguments.length)
      return this._entityIDs;
    if (!val || !this._entityIDs || !utilArrayIdentical(this._entityIDs, val)) {
      this._entityIDs = val;
      this._uifields = null;
    }
    return this;
  }
}
