    const l10n = context2.systems.l10n;
    const osm = context2.services.osm;
    const viewport = context2.viewport;
    if (!osm)
      return;
    if (this._lastv === viewport.v)
      return;
    let $wrap = $parent.selectAll(".contributors").data([0]);
    const $$wrap = $wrap.enter().append("div").attr("class", "contributors");
    $$wrap.call(uiIcon("#rapid-icon-nearby", "pre-text light"));
