// modules/operations/DeleteOperation.ts
class DeleteOperation extends AbstractOperation {
  _entities;
  _isNew;
  _action;
  _coords;
  _extent;
  constructor(context2, selectedIDs) {
    super(context2, selectedIDs);
    const editor = context2.systems.editor;
    const l10n = context2.systems.l10n;
    const graph = editor.staging.graph;
    this._entities = selectedIDs.map((entityID) => graph.hasEntity(entityID)).filter(Boolean);
    this._isNew = this._entities.every((entity) => entity.isNew());
    this._action = actionDeleteMultiple(selectedIDs);
    this._coords = utilGetAllNodes(selectedIDs, graph).map((node) => node.loc);
    this._extent = utilTotalExtent(this._entities, graph);
    this.id = "delete";
    this.keys = [utilCmd("⌘⌫"), utilCmd("⌘⌦"), utilCmd("⌦")];
    this.title = l10n.t("operations.delete.title");
    this.behavior = new KeyOperationBehavior(context2, this);
  }
  run() {
    const context2 = this.context;
    const editor = context2.systems.editor;
    const map2 = context2.systems.map;
    const graph = editor.staging.graph;
    let nextNode;
    let nextLoc;
    if (this._entities.length === 1) {
      const entity = this._entities[0];
      const geometry = entity.geometry(graph);
      const parents = graph.parentWays(entity);
      const parent = parents[0];
      if (geometry === "vertex") {
        const nodes = parent.nodes;
        let i2 = nodes.indexOf(entity.id);
        if (i2 === 0) {
          i2++;
        } else if (i2 === nodes.length - 1) {
          i2--;
        } else {
          const a2 = geoSphericalDistance(entity.loc, graph.entity(nodes[i2 - 1]).loc);
          const b3 = geoSphericalDistance(entity.loc, graph.entity(nodes[i2 + 1]).loc);
          i2 = a2 < b3 ? i2 - 1 : i2 + 1;
        }
        nextNode = graph.entity(nodes[i2]);
        nextLoc = nextNode.loc;
      }
    }
    const annotation = this.annotation();
    editor.perform(this._action);
    editor.commit({ annotation, selectedIDs: this.selectedIDs });
    if (nextNode && nextLoc) {
      map2.centerEase(nextLoc);
      context2.enter("select-osm", { selection: { osm: [nextNode.id] } });
    } else {
      context2.enter("browse");
    }
  }
  available() {
    return true;
  }
  disabled() {
    const context2 = this.context;
    const editor = context2.systems.editor;
    const settings = context2.systems.settings;
    const viewport = context2.viewport;
    const graph = editor.staging.graph;
    const coords = this._coords;
    const extent = this._extent;
    const isNew = this._isNew;
    if (!isNew && tooLarge()) {
      return "too_large";
    } else if (!isNew && notDownloaded()) {
      return "not_downloaded";
    } else if (this.selectedIDs.some(context2.hasHiddenConnections)) {
      return "connected_to_hidden";
    } else if (this.selectedIDs.some(protectedMember)) {
      return "part_of_relation";
    } else if (this.selectedIDs.some(incompleteRelation)) {
      return "incomplete_relation";
    } else if (this.selectedIDs.some(hasWikidataTag)) {
      return "has_wikidata_tag";
    }
    return false;
    function tooLarge() {
      const allowLargeEdits = settings?.get("poweruser.allowLargeEdits") === "true";
      return !allowLargeEdits && extent.percentContainedIn(viewport.visibleExtent()) < 0.8;
    }
    function notDownloaded() {
      if (context2.inIntro)
        return false;
      const osm = context2.services.osm;
      if (osm) {
        const missing = coords.filter((loc) => !osm.isDataLoaded(loc));
        if (missing.length) {
          missing.forEach((loc) => context2.loadTileAtLoc(loc));
          return true;
        }
      }
      return false;
    }
    function hasWikidataTag(id) {
      const entity = graph.entity(id);
      return Boolean(entity.tags.wikidata && entity.tags.wikidata.trim().length > 0);
    }
    function incompleteRelation(id) {
      const entity = graph.entity(id);
      return entity.type === "relation" && !entity.isComplete(graph);
    }
    function protectedMember(id) {
      const entity = graph.entity(id);
      if (entity.type !== "way")
        return false;
      const parents = graph.parentRelations(entity);
      for (const parent of parents) {
        const type = parent.tags.type;
        const role = parent.memberById(id)?.role || "outer";
        if (type === "route" || type === "boundary" || type === "multipolygon" && role === "outer") {
          return true;
        }
      }
      return false;
    }
  }
  tooltip() {
    const l10n = this.context.systems.l10n;
    const disabledReason = this.disabled();
    return disabledReason ? l10n.t(`operations.delete.${disabledReason}`, { n: this.selectedIDs.length }) : l10n.t(`operations.delete.description`, { n: this.selectedIDs.length });
  }
  annotation() {
    const editor = this.context.systems.editor;
    const l10n = this.context.systems.l10n;
    if (this.selectedIDs.length === 1) {
      const graph = editor.staging.graph;
      const entity = graph.entity(this.selectedIDs[0]);
      return l10n.t("operations.delete.annotation." + entity.geometry(graph));
    } else {
      return l10n.t("operations.delete.annotation.feature", { n: this.selectedIDs.length });
    }
  }
}

