    const $$tagBag = $$tagInfo.append("div").attr("class", "tag-bag");
    $$tagBag.append("div").attr("class", "tag-heading");
    $tagInfo = $tagInfo.merge($$tagInfo);
    $tagInfo.selectAll(".tag-heading").text(l10n.t("text.tag", { n: tagData.length }));
    const $bag = $tagInfo.selectAll(".tag-bag");
    const $items = $bag.selectAll(".tag-entry").data(tagData, (d2) => d2[0]);
    $items.exit().remove();
    const $$items = $items.enter().append("div").attr("class", "tag-entry");
    $$items.append("div").attr("class", "tag-key").text((d2) => d2[0]);
