    const dictionary = ds.dictionary;
    let $choices = $parent.selectAll(".rapid-inspector-choices").data(dictionary ? [0] : []);
    $choices.exit().remove();
    const $$choices = $choices.enter().append("div").attr("class", "rapid-inspector-choices");
    $$choices.append("p").attr("class", "rapid-inspector-prompt");
    $$choices.selectAll(".rapid-inspector-choice").data(choiceData, (d2) => d2.key).enter().append("div").attr("class", (d2) => `rapid-inspector-choice rapid-inspector-choice-${d2.key}`);
