    const $$details = $$items.append("div").attr("class", "error-detail-container").style("display", "none");
    $$details.append("ul").attr("class", "error-detail-list").selectAll("li").data((d2) => d2?.details || []).enter().append("li").attr("class", "error-detail-item").text((d2) => d2);
    $items.exit().remove();
