// modules/operations/OrthogonalizeOperation.ts
class OrthogonalizeOperation extends AbstractOperation {
  _entities;
  _isNew;
  _extent;
  _type;
  _actions;
  _coords;
  constructor(context2, selectedIDs) {
    super(context2, selectedIDs);
    const editor = context2.systems.editor;
    const l10n = context2.systems.l10n;
    const graph = editor.staging.graph;
    this._entities = selectedIDs.map((entityID) => graph.hasEntity(entityID)).filter(Boolean);
    this._isNew = this._entities.every((entity) => entity.isNew());
    this._extent = utilTotalExtent(this._entities, graph);
    this._actions = this._entities.map((entity) => this._getAction(entity)).filter(Boolean);
    this._coords = utilGetAllNodes(selectedIDs, graph).map((node) => node.loc);
    this.id = "orthogonalize";
    this.keys = [l10n.t("shortcuts.command.orthogonalize.key")];
    this.title = l10n.t("operations.orthogonalize.title");
    this.behavior = new KeyOperationBehavior(context2, this);
  }
  run() {
    const editor = this.context.systems.editor;
    if (!this._actions.length)
      return;
    const actions = this._actions;
    const combinedAction = (graph, t2) => {
      for (const action of actions) {
        if (!action.disabled?.(graph)) {
          graph = action(graph, t2);
        }
      }
      return graph;
    };
    combinedAction.transitionable = true;
    const annotation = this.annotation();
    editor.performAsync(combinedAction).then(() => editor.commit({ annotation, selectedIDs: this.selectedIDs }));
  }
  available() {
    return this._actions.length > 0 && this.selectedIDs.length === this._actions.length;
  }
  disabled() {
    const context2 = this.context;
    const editor = context2.systems.editor;
    const settings2 = context2.systems.settings;
    const viewport = context2.viewport;
    if (!this._actions.length)
      return "";
    const graph = editor.staging.graph;
    const coords = this._coords;
    const extent = this._extent;
    const isNew = this._isNew;
    const disabledReasons = this._actions.map((action) => action.disabled?.(graph)).filter(Boolean);
    if (disabledReasons.length === this._actions.length) {
      if (new Set(disabledReasons).size > 1) {
        return "multiple_blockers";
      }
      return disabledReasons[0];
    } else if (!isNew && tooLarge()) {
      return "too_large";
    } else if (!isNew && notDownloaded()) {
      return "not_downloaded";
    } else if (this.selectedIDs.some(context2.hasHiddenConnections)) {
      return "connected_to_hidden";
    }
    return false;
    function tooLarge() {
      const allowLargeEdits = settings2?.get("poweruser.allowLargeEdits") === "true";
      return !allowLargeEdits && extent.percentContainedIn(viewport.visibleExtent()) < 0.8;
    }
    function notDownloaded() {
      if (context2.inIntro)
        return false;
      const osm = context2.services.osm;
      if (osm) {
        const missing = coords.filter((loc) => !osm.isDataLoaded(loc));
        if (missing.length) {
          missing.forEach((loc) => context2.loadTileAtLoc(loc));
          return true;
        }
      }
      return false;
    }
  }
  tooltip() {
    const l10n = this.context.systems.l10n;
    const disabledReason = this.disabled();
    return disabledReason ? l10n.t(`operations.orthogonalize.${disabledReason}`, { n: this.selectedIDs.length }) : l10n.t(`operations.orthogonalize.description.${this._type}`, { n: this.selectedIDs.length });
  }
  annotation() {
    const l10n = this.context.systems.l10n;
    return l10n.t("operations.orthogonalize.annotation." + this._type, { n: this._actions.length });
  }
  _getAction(entity) {
    const editor = this.context.systems.editor;
    const graph = editor.staging.graph;
    const geometry = entity.geometry(graph);
    if (entity.type === "way" && new Set(entity.nodes).size > 2) {
      if (this._type && this._type !== "feature")
        return null;
      this._type = "feature";
      return actionOrthogonalize(entity.id);
    } else if (geometry === "vertex") {
      if (this._type && this._type !== "corner")
        return null;
      this._type = "corner";
      const parents = graph.parentWays(entity);
      if (parents.length === 1) {
        const way = parents[0];
        if (way.nodes.indexOf(entity.id) !== -1) {
          return actionOrthogonalize(way.id, entity.id);
        }
      }
    }
    return null;
  }
}

