// modules/operations/ReverseOperation.ts
class ReverseOperation extends AbstractOperation {
  _actions;
  _reverseType;
  constructor(context2, selectedIDs) {
    super(context2, selectedIDs);
    const l10n = context2.systems.l10n;
    this._actions = selectedIDs.map((entityID) => this._getAction(entityID)).filter(Boolean);
    this._reverseType = this._getReverseType();
    this.id = "reverse";
    this.keys = [l10n.t("shortcuts.command.reverse.key")];
    this.title = l10n.t("operations.reverse.title");
    this.behavior = new KeyOperationBehavior(context2, this);
  }
  run() {
    const editor = this.context.systems.editor;
    if (!this._actions.length)
      return;
    const actions = this._actions;
    const combinedAction = (graph) => {
      for (const action of actions) {
        graph = action(graph);
      }
      return graph;
    };
    const annotation = this.annotation();
    editor.perform(combinedAction);
    editor.commit({ annotation, selectedIDs: this.selectedIDs });
  }
  available() {
    return this._actions.length > 0;
  }
  tooltip() {
    const l10n = this.context.systems.l10n;
    return l10n.t(`operations.reverse.description.${this._reverseType}`);
  }
  annotation() {
    const l10n = this.context.systems.l10n;
    return l10n.t(`operations.reverse.annotation.${this._reverseType}`, { n: this._actions.length });
  }
  _getAction(entityID) {
    const editor = this.context.systems.editor;
    const graph = editor.staging.graph;
    const entity = graph.hasEntity(entityID);
    if (!entity)
      return null;
    const geometry = entity.geometry(graph);
    if (entity.type !== "node" && geometry !== "line")
      return null;
    const action = actionReverse(entityID);
    if (action.disabled(graph))
      return null;
    return action;
  }
  _getReverseType() {
    const editor = this.context.systems.editor;
    const graph = editor.staging.graph;
    const nodeActionCount = this._actions.filter((action) => {
      const entity = graph.hasEntity(action.entityID());
      return entity?.type === "node";
    }).length;
    if (nodeActionCount === 0)
      return "line";
    if (nodeActionCount === this._actions.length)
      return "point";
    return "feature";
  }
}

