// modules/operations/SplitOperation.ts
class SplitOperation extends AbstractOperation {
  _vertexIDs;
  _vertexMulti;
  _wayIDs;
  _isAvailable;
  _action;
  _geometry;
  _splittable;
  _waysMulti;
  constructor(context2, selectedIDs) {
    super(context2, selectedIDs);
    const editor = context2.systems.editor;
    const l10n = context2.systems.l10n;
    const graph = editor.staging.graph;
    const entities = selectedIDs.map((entityID) => graph.hasEntity(entityID)).filter(Boolean);
    const vertices = entities.filter((entity) => entity.type === "node" && entity.geometry(graph) === "vertex");
    const ways = entities.filter((entity) => entity.type === "way");
    this._vertexIDs = vertices.map((entity) => entity.id);
    this._vertexMulti = this._vertexIDs.length === 1 ? "single" : "multiple";
    this._wayIDs = ways.map((entity) => entity.id);
    this._isAvailable = vertices.length > 0 && vertices.length + ways.length === selectedIDs.length;
    this._action = actionSplit(this._vertexIDs);
    this._geometry = "feature";
    this._splittable = [];
    this._waysMulti = "single";
    if (this._isAvailable) {
      if (this._wayIDs.length) {
        this._action.limitWays(this._wayIDs);
      }
      this._splittable = this._action.ways(graph);
      const geometries = new Set;
      for (const way of this._splittable) {
        geometries.add(way.geometry(graph));
      }
      if (geometries.size === 1) {
        this._geometry = Array.from(geometries)[0];
      }
      this._waysMulti = this._splittable.length === 1 ? "single" : "multiple";
    }
    this.id = "split";
    this.keys = [l10n.t("shortcuts.command.split.key")];
    this.title = l10n.t("operations.split.title");
    this.behavior = new KeyOperationBehavior(context2, this);
  }
  run() {
    const context2 = this.context;
    const editor = context2.systems.editor;
    const annotation = this.annotation();
    const difference2 = editor.perform(this._action);
    editor.commit({ annotation, selectedIDs: this.selectedIDs });
    const idsToSelect = this._vertexIDs.slice();
    if (difference2) {
      for (const [entityID, change] of difference2.changes) {
        const entity = change.head;
        if (entity && entity.type === "way") {
          idsToSelect.push(entityID);
        }
      }
    }
    context2.enter("select-osm", { selection: { osm: idsToSelect } });
  }
  relatedEntityIds() {
    return this._splittable.map((way) => way.id);
  }
  available() {
    return this._isAvailable;
  }
  disabled() {
    const context2 = this.context;
    const editor = context2.systems.editor;
    const graph = editor.staging.graph;
    const disabledReason = this._action.disabled?.(graph);
    if (disabledReason) {
      return disabledReason;
    } else if (this.selectedIDs.some(context2.hasHiddenConnections)) {
      return "connected_to_hidden";
    }
    return false;
  }
  tooltip() {
    const l10n = this.context.systems.l10n;
    const disabledReason = this.disabled();
    return disabledReason ? l10n.t(`operations.split.${disabledReason}`) : l10n.t(`operations.split.description.${this._geometry}.${this._waysMulti}.${this._vertexMulti}_node`);
  }
  annotation() {
    const l10n = this.context.systems.l10n;
    return l10n.t(`operations.split.annotation.${this._geometry}`, { n: this._splittable.length });
  }
}

// modules/operations/StraightenOperation.ts
class StraightenOperation extends AbstractOperation {
  _entities;
  _isNew;
  _ways;
  _wayIDs;
  _nodes;
  _nodeIDs;
  _coords;
  _extent;
  _geometry;
  _action;
  constructor(context2, selectedIDs) {
    super(context2, selectedIDs);
    const editor = context2.systems.editor;
    const l10n = context2.systems.l10n;
    const graph = editor.staging.graph;
    this._entities = selectedIDs.map((entityID) => graph.hasEntity(entityID)).filter(Boolean);
    this._isNew = this._entities.every((entity) => entity.isNew());
    this._ways = this._entities.filter((entity) => entity.type === "way");
    this._wayIDs = this._ways.map((entity) => entity.id);
    this._nodes = this._entities.filter((entity) => entity.type === "node");
    this._nodeIDs = this._nodes.map((entity) => entity.id);
    this._coords = utilGetAllNodes(selectedIDs, graph).map((node) => node.loc);
    this._extent = utilTotalExtent(selectedIDs, graph);
    this._action = this._chooseAction();
    this.id = "straighten";
    this.keys = [l10n.t("shortcuts.command.straighten.key")];
    this.title = l10n.t("operations.straighten.title");
    this.behavior = new KeyOperationBehavior(context2, this);
  }
  run() {
    const editor = this.context.systems.editor;
    const action = this._action;
    if (!action)
      return;
    const annotation = this.annotation();
    editor.performAsync(action).then(() => editor.commit({ annotation, selectedIDs: this.selectedIDs }));
  }
  available() {
    return Boolean(this._action);
  }
  disabled() {
    const context2 = this.context;
    const editor = context2.systems.editor;
    const settings2 = context2.systems.settings;
    const viewport = context2.viewport;
    const action = this._action;
    if (!action)
      return false;
    const graph = editor.staging.graph;
    const coords = this._coords;
    const extent = this._extent;
    const isNew = this._isNew;
    const disabledReason = action.disabled?.(graph);
    if (disabledReason) {
      return disabledReason;
    } else if (!isNew && tooLarge()) {
      return "too_large";
    } else if (!isNew && notDownloaded()) {
      return "not_downloaded";
    } else if (this.selectedIDs.some(context2.hasHiddenConnections)) {
      return "connected_to_hidden";
    }
    return false;
    function tooLarge() {
      const allowLargeEdits = settings2?.get("poweruser.allowLargeEdits") === "true";
      return !allowLargeEdits && extent.percentContainedIn(viewport.visibleExtent()) < 0.8;
    }
    function notDownloaded() {
      if (context2.inIntro)
        return false;
      const osm = context2.services.osm;
      if (osm) {
        const missing = coords.filter((loc) => !osm.isDataLoaded(loc));
        if (missing.length) {
          missing.forEach((loc) => context2.loadTileAtLoc(loc));
          return true;
        }
      }
      return false;
    }
  }
  tooltip() {
    const l10n = this.context.systems.l10n;
    const disabledReason = this.disabled();
    return disabledReason ? l10n.t(`operations.straighten.${disabledReason}`, { n: this._ways.length || this._nodes.length }) : l10n.t(`operations.straighten.description.${this._geometry}` + (this._ways.length === 1 ? "" : "s"));
  }
  annotation() {
    const l10n = this.context.systems.l10n;
    return l10n.t(`operations.straighten.annotation.${this._geometry}`, { n: this._ways.length || this._nodes.length });
  }
  _chooseAction() {
    const editor = this.context.systems.editor;
    const graph = editor.staging.graph;
    const ways = this._ways;
    const nodes = this._nodes;
    const nodeIDs = this._nodeIDs;
    const wayIDs = this._wayIDs;
    if (ways.length === 0 && nodes.length > 2) {
      this._geometry = "point";
      return actionStraightenNodes(nodeIDs);
    } else if (ways.length > 0 && (nodes.length === 0 || nodes.length === 2)) {
      let startNodeIDs = [];
      let endNodeIDs = [];
      for (const entity of this._entities) {
        if (entity.type !== "way")
          continue;
        const way = entity;
        if (way.isClosed())
          return null;
        startNodeIDs.push(way.first());
        endNodeIDs.push(way.last());
      }
      startNodeIDs = startNodeIDs.filter((nodeID) => startNodeIDs.indexOf(nodeID) === startNodeIDs.lastIndexOf(nodeID));
      endNodeIDs = endNodeIDs.filter((nodeID) => endNodeIDs.indexOf(nodeID) === endNodeIDs.lastIndexOf(nodeID));
      if (utilArrayDifference(startNodeIDs, endNodeIDs).length + utilArrayDifference(endNodeIDs, startNodeIDs).length !== 2)
        return null;
      const wayNodeIDs = utilGetAllNodes(wayIDs, graph).map((node) => node.id);
      if (wayNodeIDs.length <= 2)
        return null;
      if (nodeIDs.length === 2 && (wayNodeIDs.indexOf(nodeIDs[0]) === -1 || wayNodeIDs.indexOf(nodeIDs[1]) === -1))
        return null;
      if (nodeIDs.length) {
        this._extent = utilTotalExtent(nodeIDs, graph);
      }
      this._geometry = "line";
      return actionStraightenWay(this.selectedIDs);
    }
    return null;
  }
}

