    const metadataURLBase = "https://dev.virtualearth.net/REST/v1/Imagery/MetaData/Streetside";
    const metadataKey = "AoG8TaQvkPo6o8SlpRVmBs7WJwO_NDQklVRcAfpn7P8oiEMYWNY59XHSJU81sP1Y";
